// Mobility: how well the drone moves this turn, set from its Power, Health and build.
const power = owner.stats.Power;
const health = owner.stats.Health;
const traits = owner.traits;

// The share of Power left sets the base: 15 when drained, 85 when full.
let mobility = (power.value / power.max) * 70 + 15;

// The chassis shifts the base: Scout is light and fast, Siege is heavy and slow.
if (traits["Scout Frame"].enabled) mobility += 10;
if (traits["Siege Frame"].enabled) mobility -= 15;

// Evasion Thrusters add bursts of speed on top.
if (traits["Evasion Thrusters"].enabled) mobility += 15;

// Below 30% of max Health the core fails, so movement caps out low.
// A share of max, not a fixed number, keeps the line fair on every chassis.
if (health.value / health.max < 0.3) mobility = Math.min(mobility, 35);

// The stat clamps the result to 0–100.
return Math.round(mobility);

// Firepower: how hard the drone's weapons hit this turn, set from its Power, Health, Charge and build.
const power = owner.stats.Power;
const health = owner.stats.Health;
const charge = owner.stats.Charge;
const traits = owner.traits;

// The share of Power left sets the base: 10 when drained, 80 when full.
let firepower = (power.value / power.max) * 70 + 10;

// Each weapon part adds its own bonus.
if (traits["Assault Frame"].enabled) firepower += 5;
if (traits["Overcharged Rounds"].enabled) firepower += 10;
if (traits["Recon Optics"].enabled) firepower += 5;
if (traits["Siege Cannon"].enabled) firepower += 15;

// Below 30% of max Health the failing core halves the output.
if (health.value / health.max < 0.3) firepower *= 0.5;

// Full Charge primes the Overdrive burst, a large spike on top.
if (charge.value >= charge.max) firepower += 30;

// The stat clamps the result to 0–100.
return Math.round(firepower);

