// Berserk: how deep the frenzy runs. Berserk State switches this stat on, so this script runs only during a frenzy.
const health = owner.stats.Health;
const rampage = owner.stats.Rampage;

// Each turn of frenzy sinks a quarter of the way deeper, so four turns in a row reach the bottom.
const berserk = Math.min(self.previous.value + self.max * 0.25, self.max);

// How far down the frenzy is, from 0 at the top to 1 at the bottom. The two costs below scale with it.
const depth = berserk / self.max;

// The frenzy feeds the fury: 5 Rampage a turn at the start, up to 15 at the bottom.
rampage.value = rampage.value + 5 + Math.round(depth * 10);

// The wounds stay open: Health loses a share of its max, 4% at the start, up to 10% at the bottom.
// A share of max, not a fixed number, keeps the cost fair on every body (Armored Hide raises the max).
health.value = health.value - Math.round(health.max * (0.04 + depth * 0.06));

// The stat clamps the result to 0–100.
return Math.round(berserk);

// Berserk State: starts each frenzy fresh.
// The Berserk stat keeps its value while it is switched off, so a new frenzy would start where the last one stopped.
// When the trait switches on, the stat switches on with it, and this clears it back to zero.
if (trait.enabled) owner.stats.Berserk.value = 0;

