// Hunger tick: the curse climbs one step every turn, however much story time the turn took.
// This script runs after the AI's change, so a meal the AI already took off this turn stays off.
const fullness = owner.stats.Fullness;
const traits = owner.traits;

// Every curse starts from the same base step.
let step = 3;

// Appetite sets how loud the curse runs. Exactly one of these is on.
if (traits.Grazer.enabled) step -= 1;
if (traits.Glutton.enabled) step += 2;
if (traits["Iron Will"].enabled) step -= 2;

// Pantry Tricks tilt it further: a satisfying meal lasts, a sugar rush burns off fast.
if (traits["Hearty Appetite"].enabled) step -= 1;
if (traits["Sugar Rush"].enabled) step += 1;

// An empty stomach feeds the curse, and a full one muffles it.
// A share of max, not a fixed number, so a Glutton's bigger stomach reads the same way.
const fullShare = fullness.value / fullness.max;
if (fullShare < 0.1) step += 2;
else if (fullShare >= 0.7) step -= 1;

// Gritted Teeth beats the curse back while the player holds it. Craving falls every turn,
// at least one point even for a hungry Glutton, and more for a calm appetite.
if (traits["Gritted Teeth"].enabled) step = Math.min(step - 4, -1);

// Add the step to this turn's value. The stat clamps the result to 0–100.
return self.value + step;

